export const MOVES={riposte:{name:'Skillet Return',icon:'◈',desc:'Deal 11 damage. Ignore all armor and guard.',cd:2},heavy:{name:'Titan Chop',icon:'✦',desc:'Deal 19 damage. Take 4 recoil damage.',cd:3},drain:{name:'Blood Ribbon',icon:'♥',desc:'Deal 9 damage. Recover 7 health.',cd:3},flurry:{name:'Twin Sunbreak',icon:'✧',desc:'Two hits of 7 damage. Great with weapon upgrades.',cd:2},brace:{name:'Ironroot',icon:'⬡',desc:'Block 16 damage this turn. Next attack gains 7 damage.',cd:3},venom:{name:'Bog Venom',icon:'⌁',desc:'Deal 5 damage. Poison deals 4 damage for 3 turns.',cd:3},crown:{name:'Fairy Ring',icon:'♛',desc:'Deal 16 damage and block 8 this turn.',cd:3}};
export const HEROES={
  miri:{name:'Miri Brass',title:'The Counterblade',desc:'Balanced and precise. Perfect guards empower her next strike.',innate:'Royal Riposte',color:'#ef6854'},
  tovin:{name:'Tovin Rook',title:'The Stoneheart',desc:'Slow, powerful and hard to move. He begins with more health and armor.',innate:'Hold Fast',color:'#3fa9a4'},
  suri:{name:'Suri Vell',title:'The Threadstep',desc:'Fast and elusive. Dodges leave a spark for the next attack.',innate:'Threadstep',color:'#8d68d8'}
};
export const REGIONS=[
  {name:'Embermeadow Circuit',subtitle:'The road of bright challengers',rounds:[0,1,2,3],master:3},
  {name:'Murkmirror Fen',subtitle:'Where every victory has a reflection',rounds:[4,5,6],master:6}
];
export const FOES=[{name:'Odo Copperpot',title:'The cook-knight',hp:44,armor:1,move:'riposte',art:1,pattern:[['attack',8],['guard',8],['attack',12]]},{name:'Bramble Jack',title:'The orchard headsman',hp:53,armor:0,move:'heavy',art:2,pattern:[['charge',0],['attack',21],['attack',9]]},{name:'Renn Ribbonfox',title:'The fairground lancer',hp:56,armor:1,move:'drain',art:3,pattern:[['drain',10],['attack',11],['guard',9]]},{name:'Dame Solara',title:'Master of the Sunmane',hp:62,armor:0,move:'flurry',art:4,pattern:[['double',7],['attack',12],['guard',8]]},{name:'Boldo Mossback',title:'The fen gatekeeper',hp:70,armor:3,move:'brace',art:1,pattern:[['guard',12],['attack',17],['attack',12]]},{name:'Vexa Croak',title:'The bog alchemist',hp:71,armor:1,move:'venom',art:5,pattern:[['poison',10],['attack',13],['charge',0],['attack',22]]},{name:'Mother Mycelia',title:'Master of the Murkmirror',hp:100,armor:2,move:'crown',art:2,pattern:[['attack',16],['guard',14],['double',10],['charge',0],['attack',28]]}];
export const BASIC={attack:{name:'Strike',icon:'⚔',desc:'10 damage. Recover 1 energy.',cost:0,range:1},power:{name:'Heavy strike',icon:'✦',desc:'17 damage. Cuts guard in half.',cost:3,range:1},guard:{name:'Guard',icon:'⬡',desc:'Block 12. Full block primes +2 damage.',cost:0},dodge:{name:'Dodge',icon:'↶',desc:'Evade one hit. Next attack +4. Recharges in 2 turns.',cost:3},forward:{name:'Leap in',icon:'↗',desc:'Jump forward up to 2 spaces. Next attack gains 3.',cost:2},back:{name:'Leap back',icon:'↙',desc:'Jump back up to 2 spaces. Escape melee range.',cost:2},rest:{name:'Recover',icon:'◉',desc:'Recover 3 energy. No protection.',cost:0}};
export function newRun(name='Gladiator',hero='miri'){const id=HEROES[hero]?hero:'miri',start=id==='tovin'?{hp:84,weapon:0,armor:1}:id==='suri'?{hp:64,weapon:1,armor:0}:{hp:72,weapon:0,armor:0};return {version:2,name:name.slice(0,18),hero:id,stage:'battle',round:0,hp:start.hp,maxHp:start.hp,weapon:start.weapon,armor:start.armor,gold:0,moves:[],cool:{},turn:0,bonus:0,poison:0,enemyPoison:0,foeHp:44,energy:6,playerPos:2,enemyPos:5,log:['Close the distance. Leap in to reach your rival.'],rewardTaken:false,gear:[],equipped:null,laurels:0};}
export function migrate(s){s.version=2;s.hero=HEROES[s.hero]?s.hero:'miri';s.energy??=6;s.playerPos??=2;s.enemyPos??=5;s.gear??=[];s.equipped??=null;s.laurels??=0;return s;}
export function distance(s){return s.enemyPos-s.playerPos;}
export function intent(s){return FOES[s.round].pattern[s.turn%FOES[s.round].pattern.length];}
export function enemyPlan(s){const plan=intent(s);if(['charge','guard'].includes(plan[0]))return plan;const range=['drain','poison'].includes(plan[0])?3:1;return distance(s)>range?['approach',Math.min(2,distance(s)-1)]:plan;}
export function unavailable(s,id){migrate(s);if(s.stage!=='battle')return 'Battle ended';if(!(id in BASIC)&&!s.moves.includes(id))return 'Not learned';if(s.cool[id]>0)return `Ready in ${s.cool[id]} turns`;if((BASIC[id]?.cost||0)>s.energy)return 'Not enough energy';let range=BASIC[id]?.range;if(s.hero==='suri'&&['attack','power'].includes(id))range=2;if(MOVES[id]&&id!=='brace')range=['drain','venom'].includes(id)?3:1;if(range&&distance(s)>range)return `Need range ${range}`;if(id==='forward'&&distance(s)===1)return 'Already in reach';if(id==='back'&&s.playerPos===0)return 'Arena wall';if(id==='rest'&&s.energy===6)return 'Energy full';return '';}
export function act(s,id,events=[]){if(unavailable(s,id))return false;let log=[],block=0,evade=id==='dodge';const foe=FOES[s.round],base=intent(s);const emit=(type,extra={})=>events.push({type,...extra,hp:s.hp,foeHp:s.foeHp,playerPos:s.playerPos,enemyPos:s.enemyPos,energy:s.energy});s.energy-=BASIC[id]?.cost||0;Object.keys(s.cool).forEach(k=>s.cool[k]=Math.max(0,s.cool[k]-1));emit('stance',{actor:'player',move:id});
const heal=(side,n)=>{const before=side==='player'?s.hp:s.foeHp;if(side==='player')s.hp=Math.min(s.maxHp,s.hp+n);else s.foeHp=Math.min(foe.hp,s.foeHp+n);emit('heal',{target:side,amount:(side==='player'?s.hp:s.foeHp)-before});};
const hit=(n,pierce=false)=>{const shield=base[0]==='guard'?base[1]:0;const defense=pierce?0:foe.armor+(id==='power'?Math.floor(shield/2):shield);const damage=Math.min(s.foeHp,Math.max(1,n+s.weapon+s.bonus-defense));s.bonus=0;s.foeHp-=damage;emit('hit',{actor:'player',target:'enemy',move:id,damage,guarded:shield>0&&!pierce});return damage;};
if(id==='attack'){log.push(`Strike deals ${hit(s.hero==='suri'?8:10)} damage.`);s.energy=Math.min(6,s.energy+1);}if(id==='power')log.push(`Heavy strike deals ${hit(s.hero==='tovin'?20:17)} damage.`);
if(id==='guard'){block=s.hero==='tovin'?14:12;s.energy=Math.min(6,s.energy+1);log.push('Guard raised. Recover 1 energy.');}
if(id==='rest'){s.energy=Math.min(6,s.energy+3);emit('recover',{actor:'player'});log.push('You catch your breath. Recover 3 energy.');}
if(id==='dodge'){const spark=s.hero==='suri'?5:4;s.cool.dodge=2;s.bonus=Math.max(s.bonus,spark);emit('dodge',{actor:'player'});log.push(`Ready to evade one hit. Your next attack gains ${spark}.`);}
if(id==='forward'||id==='back'){const from=s.playerPos;s.playerPos=id==='forward'?Math.min(s.enemyPos-1,s.playerPos+2):Math.max(0,s.playerPos-2);if(id==='forward')s.bonus=Math.max(s.bonus,3);emit('move',{actor:'player',from,to:s.playerPos,jump:true});log.push(id==='forward'?'You leap forward. Your next attack gains 3.':'You leap back to create space.');}
if(id==='riposte')log.push(`Skillet Return pierces for ${hit(11,true)}.`);if(id==='heavy'){log.push(`Titan Chop deals ${hit(19)}.`);const damage=Math.min(4,s.hp-1);s.hp-=damage;emit('recoil',{target:'player',damage});}if(id==='drain'){log.push(`Blood Ribbon deals ${hit(9)}.`);heal('player',7);}if(id==='flurry'){const a=hit(7),b=s.foeHp>0?hit(7):0;log.push(`Twin Sunbreak deals ${a+b}.`);}if(id==='brace'){block=16;s.bonus=7;log.push('Ironroot: block 16, next attack +7.');}if(id==='venom'){log.push(`Bog Venom deals ${hit(5)} and applies poison.`);s.enemyPoison=3;}if(id==='crown'){block=8;log.push(`Fairy Ring deals ${hit(16)}.`);}if(MOVES[id])s.cool[id]=MOVES[id].cd;
if(s.enemyPoison>0&&s.foeHp>0){const damage=Math.min(4,s.foeHp);s.foeHp-=damage;s.enemyPoison--;emit('poison',{target:'enemy',damage});log.push(`Your rival takes ${damage} poison damage.`);}
if(s.foeHp===0){s.stage='reward';s.rewardTaken=false;s.log=['Victory. Choose your reward.',...log];emit('defeat',{target:'enemy'});return true;}
const plan=enemyPlan(s);const take=n=>{if(evade){evade=false;emit('evade',{actor:'enemy',target:'player',move:plan[0],damage:0});log.push('You evade the attack.');return 0;}const d=Math.min(s.hp,Math.max(0,n-s.armor-block));block=Math.max(0,block-n);s.hp-=d;emit('hit',{actor:'enemy',target:'player',move:plan[0],damage:d,guarded:['guard','brace','crown'].includes(id)});return d;};
if(plan[0]==='approach'){const from=s.enemyPos;s.enemyPos=Math.max(s.playerPos+1,s.enemyPos-2);emit('move',{actor:'enemy',from,to:s.enemyPos});log.push('Your rival advances instead of attacking.');}
if(plan[0]==='attack')log.push(`${foe.name} deals ${take(plan[1])}.`);if(plan[0]==='double'){const a=take(plan[1]),b=s.hp>0?take(plan[1]):0;log.push(`Twin strike deals ${a+b}.`);}if(plan[0]==='drain'){const d=take(plan[1]);heal('enemy',Math.min(5,d));log.push(`Your rival drains ${d}.`);}if(plan[0]==='poison'){const d=take(plan[1]);if(d>0)s.poison=2;log.push(d>0?'The poisoned blade hits.':'The poisoned blade is avoided.');}
if(plan[0]==='charge'){emit('charge',{actor:'enemy'});log.push('Your rival winds up for a heavy blow.');}if(plan[0]==='guard'){emit('guard',{actor:'enemy'});log.push('Your rival holds their guard.');}
if(id==='guard'&&events.some(e=>e.type==='hit'&&e.actor==='enemy')&&!events.some(e=>e.type==='hit'&&e.actor==='enemy'&&e.damage>0)){const counter=s.hero==='miri'?3:2;s.bonus=Math.max(s.bonus,counter);emit('counter',{actor:'player',amount:counter});log.push(`Full block. Next attack gains ${counter} damage.`);}
if(s.poison>0&&s.hp>0){const damage=Math.min(3,s.hp);s.hp-=damage;s.poison--;emit('poison',{target:'player',damage});log.push(`You take ${damage} poison damage.`);}s.turn++;s.log=log;if(s.hp===0){s.stage='lost';emit('defeat',{target:'player'});}return true;}
export const tributeValue=s=>30+s.round*4;
export function reward(s,choice,replace){if(s.stage!=='reward'||s.rewardTaken)return false;const m=FOES[s.round].move;if(choice==='move'){if(s.moves.length>=3){if(!s.moves.includes(replace))return false;s.moves[s.moves.indexOf(replace)]=m;}else s.moves.push(m);}else if(choice==='gear'){const item={id:`trophy-${s.round}`,name:`${FOES[s.round].name.split(' ')[0]}'s ${s.round%2?'ward':'edge'}`,kind:s.round%2?'armor':'weapon',tier:s.round===3||s.round===6?'Masterwork':'Rival'};if(!s.gear.some(g=>g.id===item.id))s.gear.push(item);s.equipped=item.id;if(item.kind==='weapon')s.weapon+=2;else s.armor+=1;}else if(choice==='gold'){s.gold+=tributeValue(s);}else return false;if([3,6].includes(s.round))s.laurels++;s.rewardTaken=true;s.stage=s.round===6?'won':'camp';return true;}
export function buy(s,item){if(s.stage!=='camp')return false;const costs={weapon:30,armor:30,heal:20};if(!(item in costs)||s.gold<costs[item]||(item==='heal'&&s.hp===s.maxHp))return false;s.gold-=costs[item];if(item==='weapon')s.weapon+=2;if(item==='armor')s.armor++;if(item==='heal')s.hp=Math.min(s.maxHp,s.hp+25);return true;}
export function next(s){if(s.stage!=='camp')return false;s.round++;s.foeHp=FOES[s.round].hp;s.hp=Math.min(s.maxHp,s.hp+10);s.turn=0;s.energy=6;s.playerPos=2;s.enemyPos=5;s.cool={};s.bonus=0;s.poison=0;s.enemyPoison=0;s.stage='battle';s.log=['You recover 10 health on the road.'];return true;}
export function enterBattle(s){if(s.stage!=='map')return false;s.stage='battle';return true;}
